import { useState } from "react";
import { useParams } from "react-router-dom"

const UpdateBooking = () => {

    const {bookingID} = useParams('');
    let [name, setName] = useState('');
    let [email, setEmail] = useState('');
    l
    let [datas, setdatas] = useState({
        // name : '',
        // email: '',
        // phoneNo: '',
        // address: ''
    })

    const handle = (e) => {
        setdatas({...datas, [e.target.name] : e.target.value })
    }

    const getdatas = () => {
        const url = "http://localhost:1111/main/updatebooking/" + bookingID;

        try{
            fetch(url)
            .then( res => res.json() )
            .then( info => {
                setdatas( info )
            })
        }catch(error){
            console.log(" Data Processing eroor.... ")
        }
    }

    useState( () => {
        getdatas()
    },[])

    const handlesubmit = () => {

    }

    return(
        <div className="container">
            <h2 className="fw-bold mt-5 text-danger text-center shadow-none">Fill the Details </h2>
            <div className="row" >
                <div className="col-lg-4" ></div>
                <div className="col-lg-4 mt-4" >
                    <form className="col-12" onSubmit={handlesubmit}>

                        <div className="row mt-3" >
                            <div className="col-3" >
                                Name 
                            </div>
                            <div className="col-9" >
                                <input type="text" value={datas.name} className=" form-control " name="names" onChange={handle} placeholder="Enter Your Name" />
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-3" >
                                Email 
                            </div>
                            <div className="col-9" >
                            <input type="email" value={datas.email} className=" form-control " name="emails" onChange={handle} placeholder="Enter Your email" />
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-3" >
                                Phone No 
                            </div>
                            <div className="col-9" >
                                <input type="number" value={datas.phoneNo} className=" form-control " name="phoneno" onChange={handle} placeholder="Enter Your Number" />
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-3" >
                                Address     
                            </div>
                            <div className="col-9" >
                                <textarea placeholder="Address" value={datas.address} name="address" onChange={handle} className="form-control" ></textarea>
                            </div>
                        </div>

                        <div className="row mt-3" >
                            <div className="col-3" >
                                <button className="btn btn-primary" >Submit</button>   
                            </div>
                        </div>   

                    </form>
                </div>
                <div className="col-lg-4" ></div>
            </div>
        </div>
    )
}

export default UpdateBooking
